#include <stdio.h>
#include <stdlib.h>

static void reverse(int *arr, int start, int end) {
    while (start < end) {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

static void rotate_array(int *arr, int n, int k) {
    if (n <= 1) return;
    k = k % n;
    if (k == 0) return;
    reverse(arr, 0, n - 1);
    reverse(arr, 0, k - 1);
    reverse(arr, k, n - 1);
}

int main(void) {
    int n, k;
