typedef struct {
    long long val;
    int idx;
} Element;

static int cmp_val(const void *a, const void *b) {
    const Element *ea = (const Element *)a;
    const Element *eb = (const Element *)b;
    if (ea->val < eb->val) return -1;
    if (ea->val > eb->val) return 1;
    return ea->idx - eb->idx;
}

int main(void) {
    int n;
    long long target;
    if (scanf("%d %lld", &n, &target) != 2) return 0;
    Element *elems = (Element *)malloc(n * sizeof(Element));
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) { free(elems); return 0; }
        elems[i].val = v;
        elems[i].idx = i;
    }
    qsort(elems, n, sizeof(Element), cmp_val);
    int best_i = -1, best_j = -1;
    int left = 0, right = n - 1;
    while (left < right) {
        long long sum = elems[left].val + elems[right].val;
        if (sum == target) {
            int i1 = elems[left].idx;
            int i2 = elems[right].idx;
            int u = (i1 < i2) ? i1 : i2;
            int v = (i1 < i2) ? i2 : i1;
            if (best_i == -1 || u < best_i || (u == best_i && v < best_j)) {
                best_i = u;
                best_j = v;
            }
            // Check other pairs with duplicate values
            if (elems[left].val == elems[left + 1].val) left++;
            else right--;
        } else if (sum < target) {
            left++;
        } else {
            right--;
        }
    }
    if (best_i != -1) {
        printf("%d %d\n", best_i, best_j);
    } else {
