static void merge_sorted(int *a, int m, const int *b, int n) {
    int p1 = m - 1;
    int p2 = n - 1;
    int p = m + n - 1;
    while (p1 >= 0 && p2 >= 0) {
        if (a[p1] > b[p2]) {
            a[p--] = a[p1--];
        } else {
            a[p--] = b[p2--];
        }
    }
    while (p2 >= 0) {
        a[p--] = b[p2--];
    }
}

