#include <stdio.h>
#include <stdlib.h>

#define HASH_SIZE 262144
#define MASK (HASH_SIZE - 1)

typedef struct HashNode {
    long long sum;
    int count;
    struct HashNode *next;
} HashNode;

static HashNode *table[HASH_SIZE];

static unsigned int hash_func(long long key) {
    unsigned long long x = (unsigned long long)key;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    x = x ^ (x >> 31);
    return (unsigned int)(x & MASK);
}

static int get_count(long long sum) {
    unsigned int idx = hash_func(sum);
    for (HashNode *node = table[idx]; node; node = node->next) {
        if (node->sum == sum) return node->count;
    }
    return 0;
}

static void insert_or_increment(long long sum) {
    unsigned int idx = hash_func(sum);
    for (HashNode *node = table[idx]; node; node = node->next) {
        if (node->sum == sum) {
            node->count++;
            return;
        }
    }
    HashNode *new_node = (HashNode *)malloc(sizeof(HashNode));
    new_node->sum = sum;
    new_node->count = 1;
    new_node->next = table[idx];
    table[idx] = new_node;
}

int main(void) {
    int n;
    long long k;
    if (scanf("%d %lld", &n, &k) != 2) return 0;
    int *nums = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &nums[i]) != 1) { free(nums); return 0; }
    }
    for (int i = 0; i < HASH_SIZE; i++) table[i] = NULL;
    insert_or_increment(0);
    long long current_prefix = 0;
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        current_prefix += nums[i];
        long long needed = current_prefix - k;
        ans += get_count(needed);
        insert_or_increment(current_prefix);
    }
    printf("%lld\n", ans);
    // Free hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        HashNode *node = table[i];
        while (node) {
            HashNode *tmp = node->next;
            free(node);
            node = tmp;
        }
    }
    free(nums);
    return 0;
